const META=Object.freeze(Object.fromEntries(ROWS.map(([path,track,...candidates])=>[path==='myr5'?path:`roster/${path}`,Object.freeze({track,names:Object.freeze(candidates.map(([name,person,workout,scifi])=>Object.freeze({name,person,workout,scifi})))})])));
export const COACH_NAME_META=META;
/** One or two user-selected names by stable coach id. */
export const COACH_NAMES=Object.freeze(Object.fromEntries(Object.entries(META).map(([id,m])=>[id,Object.freeze(m.names.map(n=>n.name))])));
export const normalizePun=text=>String(text).toLowerCase().normalize('NFD').replace(/[^a-z0-9]/g,'');
function metaFor(coachId){const meta=META[coachId];if(!meta)throw RangeError(`No coach name for ${coachId}.`);return meta;}
/** Primary name, or the second candidate if available. */
export const coachName=(coachId,alternative=false)=>{const names=metaFor(coachId).names;return names[alternative?1:0]?.name??names[0].name;};
/** Toggle a pair; a single-name coach keeps its selected name. */
export function cycleCoachName(coachId,current){const names=metaFor(coachId).names.map(n=>n.name);return names.length===1?names[0]:current===names[0]?names[1]:names[0];}
